/// <summary>
/// MPJ_15907_LiquorAndTobaccoLicence
/// </summary>
class METCustLicDueEmailSendService extends SysOperationServiceBase
{
    const real  RetryNum = 3;
}

Method.Source:
    /// <summary>
    /// To process business operation
    /// </summary>
    /// <param name = "_contract"> store input information </param>
    public void processOperation(METCustLicDueEmailSendContract _contract)
    {
        container   custLicDueTableRecIds = str2con(_contract.parmCustomerLicenceDueRecIds(), METConstants::Comma);
        Integer     recIdContainerCount;

        Map         templateTokens;

        str1260     emailSenderName, emailSenderAddr, emailSubject, emailBody;

        METCustParameters   custParms = METCustParameters::Find();
        if(!custParms.CustLicenceExpiryEmailTemplate)
        {
            error("@MET:METMissingEmailTemplateError");
        }
        
        SysEmailTable           emailTable = SysEmailTable::find(custParms.CustLicenceExpiryEmailTemplate);
        SysEmailMessageTable    emailMessageTable = SysEmailMessageTable::find(custParms.CustLicenceExpiryEmailTemplate, emailTable.DefaultLanguage);
        
        emailSubject    =   emailMessageTable.Subject;
        emailBody       =   emailMessageTable.Mail;
        emailSenderAddr =   emailTable.SenderAddr;
        emailSenderName =   emailTable.SenderName;

        container       toEmailIdContainer;
        for(recIdContainerCount = 1; recIdContainerCount <= conLen(custLicDueTableRecIds); recIdContainerCount++)
        {
            METCustTobaccoLicenseTable  custTobaccoLicTable;
            CustTable                   custtable;
            RefRecId                    custTobaccoLicTableRecId = conPeek(custLicDueTableRecIds, recIdContainerCount);

            select firstonly custTobaccoLicTable where custTobaccoLicTable.RecId == custTobaccoLicTableRecId;
            select firstonly Party from custtable where custtable.AccountNum == custTobaccoLicTable.CustomerNumber;

            if(!custParms.CustDefaultEmailPurpose)
            {
                error("@MET:METMissingEmailPurpose");
            }
            LogisticsLocationRoleName   llRoleName;
            llRoleName = custTobaccoLicTable.SendNotificationsTo ? custTobaccoLicTable.SendNotificationsTo : custParms.CustDefaultEmailPurpose;
            
            toEmailIdContainer = DirParty::electronicAddressLocatorsByRole(custtable.Party, LogisticsElectronicAddressMethodType::Email, llRoleName);
            Str1260 toEmailId = con2Str(toEmailIdContainer, METConstants::Comma);

            templateTokens = new Map(Types::String, Types::String);
            templateTokens.insert(METConstants::CustomerName, custTobaccoLicTable.customerName);
            templateTokens.insert(METConstants::CustomerNumber, custTobaccoLicTable.customerNumber);
            templateTokens.insert(METConstants::TobaccoLicenceNumber, custTobaccoLicTable.TobaccoLicenceNumber);
            
            SysMailerMessageBuilder messageBuilder = new SysMailerMessageBuilder();
            messageBuilder.addTo(toEmailId).setSubject(emailSubject).setBody(SysEmailMessage::stringExpand(emailBody, SysEmailTable::htmlEncodeParameters(templateTokens)));

            try
            {
                if (emailSenderAddr)
                {
                    messageBuilder.setFrom(emailSenderAddr, emailSenderName);
                    SysMailerFactory::getNonInteractiveMailer().sendNonInteractive(messageBuilder.getMessage());

                    ttsbegin;
                    custTobaccoLicTable.selectForUpdate(true);
                    custTobaccoLicTable.LastEmailSentDate = DateTimeUtil::date(DateTimeUtil::getSystemDateTime());
                    if(custTobaccoLicTable.validateWrite())
                    {
                        custTobaccoLicTable.update();
                    }
                    ttscommit;
                }
            }
            catch(Exception::Error)
            {
                info("@MET:METEmailSendError", custTobaccoLicTable.CustomerNumber);
            }
            catch(Exception::UpdateConflict)
            {
                Info("@MET:METCustTobaccoLicTableUpdateConflict", custTobaccoLicTable.CustomerNumber);
                throw Exception::UpdateConflictNotRecovered;
            }
            catch(Exception::CLRError)
            {
                System.Exception netExcepn;
                info("@MET:METRebateCLRException");
                netExcepn = CLRInterop::getLastException();
                info(netExcepn.ToString());
            }
            catch(Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                retry;
            }
        }
    }
